r niet zomaar zal laten vertrekken. De reddingspoging vraagt meer dan alleen een weg naar binnen vinden: Bobby moet door een vijandig landschap reizen en vervolgens ook weer kunnen ontsnappen. Zijn band met Casimira dwingt hem grenzen over te gaan die in zijn bestaan als engel normaal niet worden overschreden.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/550783/happy-hour-in-de-hel.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/550783/happy-hour-in-de-hel.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"bc2b40656305e223973842f2833c4b414f42bfb03b645af9bafc28681ee61d45"}]}},{"relation":"editions","ref":"edition:9789022561577","key":{"id":976200109},"before":null,"after":{"work_id":923100007,"title":"In de ban van de ring-trilogie","isbn_13":"9789022561577","isbn_10":null,"language":"nld","publisher":"Meulenhoff Boekerij B.V.","open_library_edition_id":null,"id":976200109}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022561577","key":{"edition_id":"@edition:9789022561577"},"before":null,"after":{"edition_id":"@edition:9789022561577","work_id":923100007,"bound_author_id":921300006,"bound_title":"In de ban van de ring-trilogie","bound_language":"nld","bound_isbn13":"9789022561577","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000521561_In_de_ban_van_de_ring-trilogie_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/797103/in-de-ban-van-de-ring-trilogie.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/797103/in-de-ban-van-de-ring-trilogie.html","checkedAt":"2026-11-01","sha256":"32e