reigt. Zijn zoektocht voert hem langs de eilanden en zeeën van Aardzee. Om aan het gevaar te ontsnappen moet hij meer leren dan toverspreuken: hij moet ook onder ogen zien welke verantwoordelijkheid bij zijn eigen macht hoort.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1019295/machten-van-aardzee.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1019295/machten-van-aardzee.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"725b38c79c6b9e6f5810e793ef18e0aac180818516611ebbb3670536d2eee376"}]}},{"relation":"editions","ref":"edition:9789024558858","key":{"id":976200111},"before":null,"after":{"work_id":921100025,"title":"Het spel der tronen","isbn_13":"9789024558858","isbn_10":null,"language":"nld","publisher":"Luitingh-Sijthoff B.V., Uitgeverij","open_library_edition_id":null,"id":976200111}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024558858","key":{"edition_id":"@edition:9789024558858"},"before":null,"after":{"edition_id":"@edition:9789024558858","work_id":921100025,"bound_author_id":921300020,"bound_title":"Het spel der tronen","bound_language":"nld","bound_isbn13":"9789024558858","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000096063_Het_spel_der_tronen_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/224777/het-spel-der-tronen.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/224777/het-spel-der-tronen.html","checkedAt":"2026-11-01","sha256":"359120f3f084c7024ccf75d1358155927c4f1d435c6010c33fadc28fe407f52d","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie_fcache/0000096063_Het_spel_der_tronen_0_0.jpg","checkedAt":"2026-11-01T10:56:42.227Z","sha256":"6aadf934e0822281d323f5de1d441b503d515803f64457ba8c27e65377028520","bytes":69543,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:25","key":{"work_id":921100025,"language":"nl"},"before":null,"after":{"work_id":921100025,"language":"nl","bound_author_id":921300020,"text":"Wanneer Eddard Stark wordt gevraagd de koning als diens Hand te dienen, verlaat hij het noorden voor een hof vol rivaliserende belangen. De grote families van de Zeven Koninkrijken proberen ieder hun positie veilig te stellen. Een verdachte dood en een kwetsbare opvolging maken de machtsstrijd steeds gevaarlijker. De roman volgt verschillende leden van die families en laat zien hoe politieke besluiten ook hun persoonlijke verhoudingen en toekomst bepalen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/224777/het-spel-der-tronen.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/224777/het-spel-der-tronen.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"359120f3f084c7024ccf75d1358155927c4f1d435c6010c33fadc28fe407f52d"}]}},{"relation":"editions","ref":"edition:9789056724054","key":{"id":976200112},"before":null,"after":{"work_id":8800306,"title":"Mannen die vrouwen haten","isbn_13":"9789056724054","isbn_10":null,"language":"nld","publisher":"Bruna Uitgevers B.V., A.W.","open_library_edition_id":null,"id":976200112}},{"relation":"catalog_edition_metadata","ref":"metadata:9789056724054"