beren vast te houden, zoeken andere families naar mogelijkheden om hun positie te herstellen of hun doden te wreken. De gevolgen van eerdere keuzes werken door in het dagelijks leven en in nieuwe bondgenootschappen. Dit deel van Het Lied van IJs en Vuur volgt een rijk waarin overwinning weinig zekerheid biedt.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1786926/het-lied-van-ijs-en-vuur-4-een-feestmaal-voor-kraaien.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1786926/het-lied-van-ijs-en-vuur-4-een-feestmaal-voor-kraaien.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"2c2d3df1d0b7f83b5265307962bdb101713a28c5da4284f9889542ef5c2b41db"}]}},{"relation":"editions","ref":"edition:9789022564356","key":{"id":976200115},"before":null,"after":{"work_id":924100138,"title":"De twee torens","isbn_13":"9789022564356","isbn_10":null,"language":"nld","publisher":"Meulenhoff Boekerij B.V.","open_library_edition_id":null,"id":976200115}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022564356","key":{"edition_id":"@edition:9789022564356"},"before":null,"after":{"edition_id":"@edition:9789022564356","work_id":924100138,"bound_author_id":921300006,"bound_title":"De twee torens","bound_language":"nld","bound_isbn13":"9789022564356","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000520934_De_twee_torens_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1566930/de-twee-torens.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1566930/de-twee-torens.html","checkedAt":"2026-11-01","sha256":"af7072fa6ffcd